import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/troubleshooting.md","filePath":"openshield-xdp/user-guide/troubleshooting.md","lastUpdated":1785937469000}'),i={name:"openshield-xdp/user-guide/troubleshooting.md"};function n(r,e,d,l,h,p){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="i-or-my-users-get-banned-while-uploading-files" tabindex="-1">&quot;I (or my users) get banned while uploading files&quot; <a class="header-anchor" href="#i-or-my-users-get-banned-while-uploading-files" aria-label="Permalink to &quot;&quot;I (or my users) get banned while uploading files&quot;&quot;">​</a></h2><p>This was the classic pre-2.0 false positive: SFTP/backup uploads push far more packets per second than browsing, and the per-IP BPS/PPS scorer banned the uploader.</p><p><strong>Fix (already on by default since v2.0):</strong></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ct_established_exempt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>A source that completes a real TCP session (sends actual data within <code>ct_syn_timeout_sec</code> of its SYN) is exempt from PPS/BPS/TCP scoring. Real upload clients do this automatically; spoofed floods can&#39;t fake it.</p><p>If bans persist, check in order:</p><ol><li><strong>Is the traffic actually TCP?</strong> UDP transfer tools (some backup agents, QUIC-based tools) never establish a TCP session, so there&#39;s nothing to exempt. Give the port its own limits via <a href="/pingless-studios-docs/openshield-xdp/user-guide/config-values#port-overrides-static-port-thresholds"><code>static.port_thresholds</code></a> or whitelist the peer IP.</li><li><strong>Is <code>ct_syn_timeout_sec</code> too short for your app?</strong> If the app idles longer than the timeout between bursts, the proof expires. Default is 300s; keep it above the app&#39;s keepalive interval.</li><li><strong>Are you on an old preset?</strong> Upgrades keep your existing values. v2.1.1 retuned preset scoring; run <code>sudo openshield reconfigure</code> to pick up the new numbers (or edit scores manually).</li><li><strong>Last resort:</strong> <code>sudo openshield wl add &lt;your-ip&gt;</code> — whitelisted IPs bypass everything. Fine for your office IP, wrong for customer ranges.</li></ol><h2 id="the-tui-shows-under-attack-but-nothing-is-being-dropped" tabindex="-1">&quot;The TUI shows UNDER_ATTACK but nothing is being dropped&quot; <a class="header-anchor" href="#the-tui-shows-under-attack-but-nothing-is-being-dropped" aria-label="Permalink to &quot;&quot;The TUI shows UNDER_ATTACK but nothing is being dropped&quot;&quot;">​</a></h2><p>Usually one of these:</p><ul><li><strong>Attack mode just started.</strong> The per-port cap (<code>attack_port_pps</code>) and tightened thresholds engage for the duration; check the drop counter a few seconds in — it should be climbing. <code>openshield stats</code> shows drops per stage.</li><li><strong><code>attack_port_pps</code> is set too high</strong> (or is <code>0</code> = off). The cap must sit below the flood&#39;s rate but above your busiest legit port traffic. If the flood is 50k pps at one port and your cap is 100k, nothing gets dropped at the port level — only per-IP scoring is working, and rotating floods defeat that.</li><li><strong>The attack isn&#39;t IP traffic OpenShield sees.</strong> XDP attaches per-interface; traffic arriving on a different interface (or purely local/container traffic) never reaches the program. Confirm the interface in <code>openshield status</code> matches your public traffic.</li><li><strong>Thresholds were loosened by hand.</strong> <code>attack_threshold_multiplier</code> near 1.0 means attack mode barely tightens anything. Preset default is 0.5.</li></ul><h2 id="legit-users-get-throttled-during-attacks" tabindex="-1">&quot;Legit users get throttled during attacks&quot; <a class="header-anchor" href="#legit-users-get-throttled-during-attacks" aria-label="Permalink to &quot;&quot;Legit users get throttled during attacks&quot;&quot;">​</a></h2><p>That&#39;s the per-port cap doing its job — during an attack, the attacked port&#39;s <em>total</em> rate is capped, so legit users on that port share the pain (throttled, never banned) instead of losing the server. If it&#39;s too aggressive for your service, raise <code>attack_port_pps</code> above your legit peak, or add a <code>static.port_thresholds</code> entry for that port (port overrides apply during attack mode too).</p><h2 id="how-do-i-test-this-safely" tabindex="-1">&quot;How do I test this safely?&quot; <a class="header-anchor" href="#how-do-i-test-this-safely" aria-label="Permalink to &quot;&quot;How do I test this safely?&quot;&quot;">​</a></h2><ul><li><strong>Never test from the server itself or from local containers.</strong> XDP hooks sit at NIC ingress; locally-generated traffic to your own IP doesn&#39;t cross them, so you&#39;ll &quot;test nothing&quot; and confuse yourself.</li><li>Use a second machine on another network, start small, and watch <code>openshield stats</code>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># from another host: gentle rate check against a test port</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hping3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --faster</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">server-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # SYN rate test</span></span></code></pre></div>You should see suspicion scores rise, then a ban after a few seconds.</li><li>Load with a self-timer while experimenting: <code>sudo openshield load -t 600</code> auto-unloads after 10 minutes, so a bad config can&#39;t lock you out. The interactive <code>openshield load</code> also has a 10-second safety prompt that auto-unloads if you lose access.</li><li>Whitelist your own admin IP <strong>before</strong> any aggressive test: <code>sudo openshield wl add &lt;ip&gt;</code>.</li></ul><h2 id="config-edits-don-t-seem-to-apply" tabindex="-1">&quot;Config edits don&#39;t seem to apply&quot; <a class="header-anchor" href="#config-edits-don-t-seem-to-apply" aria-label="Permalink to &quot;&quot;Config edits don&#39;t seem to apply&quot;&quot;">​</a></h2><ul><li>Run <code>sudo openshield reload</code> — most fields apply live. Fields marked 🔒 in the <a href="/pingless-studios-docs/openshield-xdp/configuration/reference">reference</a> (interface, map sizes, baseline params, <code>behavior.enabled</code>) need <code>sudo openshield unload &amp;&amp; sudo openshield load</code>.</li><li>Typos in key names are silently ignored on load in some versions; validate with <code>sudo openshield fix</code> and check <code>sudo openshield status</code>.</li><li>If the loader won&#39;t start after an edit, restore from the annotated example at <code>/opt/openshield/share/openshield.example.yaml</code>.</li></ul><h2 id="where-do-i-look-when-something-weird-happened-during-an-attack" tabindex="-1">&quot;Where do I look when something weird happened during an attack?&quot; <a class="header-anchor" href="#where-do-i-look-when-something-weird-happened-during-an-attack" aria-label="Permalink to &quot;&quot;Where do I look when something weird happened during an attack?&quot;&quot;">​</a></h2><p>Every attack writes a <strong>forensics bundle</strong> (packet capture if <code>pcap</code> is enabled, event log, ban list, and since v2.0: <code>config_snapshot.txt</code> — the mitigation config as it stood when the attack started, secrets stripped — and <code>config_changes.txt</code> — every config change made during the attack, timestamped). Since v2.2.0, attack-end reports and forensics also include a <strong>top-50 attacking-countries breakdown</strong> (IPs, peak pps/Gbps, % share; legit and established sources excluded) when GeoIP data is available — that&#39;s the fastest way to answer &quot;where did that come from?&quot; and decide whether a <a href="/pingless-studios-docs/openshield-xdp/user-guide/geo-blocking">geo block</a> is worth it. Check the TUI&#39;s attack history or the forensics directory, and pull the same data over the <a href="/pingless-studios-docs/openshield-xdp/user-guide/metrics-api">Metrics API</a> if you want it in your own tooling.</p><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/openshield-xdp/configuration/reference">Full Config Reference</a></li><li><a href="/pingless-studios-docs/openshield-xdp/getting-started/faq">FAQ</a></li><li><a href="https://discord.gg/qgBMREWWgp" target="_blank" rel="noreferrer">Discord</a></li></ul>`,21)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
